     7	function unzipList(file) {
     8	  const py = `
     9	import zipfile, sys
    10	z = zipfile.ZipFile(sys.argv[1])
    11	for n in z.namelist():
    12	    print(n)
    13	`;
    14	  const r = spawnSync('python3', ['-c', py, file], { encoding: 'utf8' });
    15	  if (r.status !== 0) {
    16	    throw new Error(r.stderr || 'unzip failed');
    17	  }
    18	  return r.stdout.split(/\r?\n/).filter(Boolean);
    19	}
    20	
    21	function main() {
    22	  const file = process.argv[2];
    23	  if (!file) {
    24	    console.error('usage: node validate.js <deck.pptx>');
    25	    process.exit(2);
    26	  }
    27	  const abs = path.resolve(file);
    28	  if (!fs.existsSync(abs)) {
    29	    console.error('missing file:', abs);
    30	    process.exit(1);
    31	  }
    32	  const names = unzipList(abs);
    33	  const slides = names.filter((n) => /^ppt\/slides\/slide\d+\.xml$/.test(n));
    34	  const charts = names.filter((n) => n.startsWith('ppt/charts/'));
    35	  const media = names.filter((n) => n.startsWith('ppt/media/'));
    36	  const issues = [];
    37	  if (slides.length === 0) issues.push('no slides in pptx zip');
    38	  if (slides.length > 20) issues.push(`too many slides (${slides.length}); keep a pitch deck ≤ 16`);
    39	  if (!names.includes('[Content_Types].xml')) issues.push('not a valid OOXML package');
    40	
    41	  const pyRead = `
    42	import zipfile, sys, re
    43	z = zipfile.ZipFile(sys.argv[1])
    44	calibri = 0
    45	white_only = 0
    46	fills = set()
    47	for n in z.namelist():
    48	    if not n.endswith('.xml'):
    49	        continue
    50	    data = z.read(n).decode('utf-8', 'ignore')
    51	    if 'Calibri' in data and n.startswith('ppt/slides/'):
    52	        calibri += 1
    53	    for m in re.finditer(r'srgbClr val="([0-9A-Fa-f]{6})"', data):
    54	        fills.add(m.group(1).upper())
    55	print('CALIBRI', calibri)
    56	print('FILLS', ','.join(sorted(fills)))
    57	`;
    58	  const info = spawnSync('python3', ['-c', pyRead, abs], { encoding: 'utf8' });
    59	  const calibri = /CALIBRI (\d+)/.exec(info.stdout || '');
    60	  const fills = /FILLS (.*)/.exec(info.stdout || '');
    61	  if (calibri && Number(calibri[1]) > 0) {
    62	    issues.push('slide XML still mentions Calibri — Office default typeface leaked in');
    63	  }
    64	  const fillSet = new Set((fills && fills[1] ? fills[1].split(',') : []).filter(Boolean));
    65	  const nonBW = [...fillSet].filter((c) => c !== 'FFFFFF' && c !== '000000');
    66	  if (nonBW.length === 0) {
